create table private.research_levels(empire_id uuid not null references public.empires(id) on delete cascade,key text not null references private.technology_catalog(key),level int not null check(level between 1 and 100),completed_at timestamptz not null,primary key(empire_id,key));
create table private.research_jobs(id uuid primary key default gen_random_uuid(),empire_id uuid not null references public.empires(id) on delete cascade,planet_id uuid not null references public.planets(id) on delete cascade,key text not null references private.technology_catalog(key),level int not null,cost bigint not null check(cost>=0),started_at timestamptz not null,finishes_at timestamptz not null,completed_at timestamptz,cancelled_at timestamptz);
create unique index research_one_planet on private.research_jobs(planet_id) where completed_at is null and cancelled_at is null;
create unique index research_one_technology on private.research_jobs(empire_id,key) where completed_at is null and cancelled_at is null;
create index research_next_completion on private.research_jobs(finishes_at) where completed_at is null and cancelled_at is null;
alter table private.research_levels enable row level security;alter table private.research_jobs enable row level security;
revoke all on private.research_levels,private.research_jobs from public,anon,authenticated;
insert into private.research_levels select empire_id,'energy',1,energy_unlocked_at from private.player_technologies where energy_unlocked_at is not null;
insert into private.research_levels select empire_id,'teleport',1,teleport_unlocked_at from private.player_technologies where teleport_unlocked_at is not null;
insert into private.research_levels select empire_id,'teleport_improved',3,teleport_unlocked_at from private.player_technologies where teleport_unlocked_at is not null;
-- Existing storage purchases remain usable; no paid reserve is reduced.
insert into private.research_levels select p.owner_empire_id,'energy_magma',case when max(p.energy_max)>75 then 4 when max(p.energy_max)>50 then 3 when max(p.energy_max)>25 then 2 else 1 end,now() from public.planets p where p.owner_empire_id is not null and p.energy_max>10 group by p.owner_empire_id;
create function private.tech_level(e uuid,k text) returns int language sql stable set search_path='' as $$select coalesce((select level from private.research_levels where empire_id=e and key=k),0)$$;
create function private.tech_price(k text,n int) returns bigint language sql stable set search_path='' as $$select case when n between 1 and (spec->>'max_level')::int then ceil((spec->>'cost')::numeric*power((spec->>'cost_growth')::numeric,n-1))::bigint end from private.technology_catalog where key=k$$;
create function private.tech_hours(k text,n int) returns numeric language sql stable set search_path='' as $$select ceil((spec->>'hours')::numeric*power((spec->>'time_growth')::numeric,n-1)) from private.technology_catalog where key=k$$;
create function private.teleport_capacity(e uuid) returns int language sql stable set search_path='' as $$select (array[1,2,3,5])[least(3,private.tech_level(e,'teleport_improved'))+1]$$;
create function private.energy_limit(e uuid) returns int language sql stable set search_path='' as $$select case private.tech_level(e,'energy_magma') when 0 then 10 when 1 then 25 when 2 then 50 when 3 then 75 else 100 end$$;
create function private.research_complete(s uuid,t timestamptz) returns void language plpgsql set search_path='' as $$
#variable_conflict use_column

declare j record;
begin
 for j in select r.* from private.research_jobs r join public.planets p on p.id=r.planet_id where p.season_id=s and r.finishes_at<=t and r.completed_at is null and r.cancelled_at is null order by r.finishes_at,r.id for update of r loop
 if not exists(select 1 from public.planets where id=j.planet_id and owner_empire_id=j.empire_id) then
  update private.research_jobs set cancelled_at=t where id=j.id;update public.empires set treasury=treasury+j.cost where id=j.empire_id;
 else
  insert into private.research_levels values(j.empire_id,j.key,j.level,t) on conflict(empire_id,key) do update set level=greatest(private.research_levels.level,excluded.level),completed_at=excluded.completed_at;
  update private.research_jobs set completed_at=t where id=j.id;
  insert into private.player_technologies(empire_id) values(j.empire_id) on conflict do nothing;
  if j.key='energy' then update private.player_technologies set energy_unlocked_at=t where empire_id=j.empire_id;update public.planets set energy=greatest(energy,10),energy_fraction=0 where owner_empire_id=j.empire_id;
  elsif j.key='teleport' then update private.player_technologies set teleport_unlocked_at=t where empire_id=j.empire_id;end if;insert into private.battle_reports(empire_id,planet_id,occurred_at,event,details) values(j.empire_id,j.planet_id,t,'research_complete',jsonb_build_object('message',(select spec->>'name' from private.technology_catalog where key=j.key)||case when j.level>1 then ' · niveau '||j.level else '' end));
 end if;
 end loop;
end $$;
create function private.research_capture() returns trigger language plpgsql set search_path='' as $$
#variable_conflict use_column
declare j record;begin
 if new.owner_empire_id is distinct from old.owner_empire_id then
 for j in update private.research_jobs set cancelled_at=coalesce(nullif(current_setting('lw.development_at',true),'')::timestamptz,now()) where planet_id=new.id and completed_at is null and cancelled_at is null returning empire_id,cost loop update public.empires set treasury=treasury+j.cost where id=j.empire_id;end loop;
 end if;return new;end $$;
create trigger research_capture before update of owner_empire_id on public.planets for each row execute function private.research_capture();
-- Keep the established command replay table; all new purchases remain server-priced.
alter function private.technology_command(text,jsonb,uuid) rename to technology_command_base;
revoke all on function private.technology_command_base(text,jsonb,uuid) from public,anon,authenticated;
create function private.technology_command(p_action text,p_args jsonb,p_request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column

declare e uuid;s uuid;p public.planets%rowtype;c jsonb;k text;n int;cost bigint;r jsonb;prev private.technology_commands%rowtype;payload jsonb;j private.research_jobs%rowtype;
begin
 select id into s from public.seasons where status='alpha' for update;e:=private.active_player_id();
 if p_action not in('research','research_cancel') then return private.technology_command_base(p_action,p_args,p_request_id);end if;
 if p_request_id is null then raise exception 'Identifiant requis.';end if;
 payload:=jsonb_build_object('action',p_action,'args',p_args);
 select * into prev from private.technology_commands where empire_id=e and request_id=p_request_id;
 if found then if prev.payload<>payload then raise exception 'Identifiant déjà utilisé pour une autre commande.';end if;return prev.result;end if;
 perform private.economy_process();
 if p_action='research_cancel' then
 select * into j from private.research_jobs where id=(p_args->>'job_id')::uuid and empire_id=e and completed_at is null and cancelled_at is null for update;
 if not found then raise exception 'Recherche déjà terminée ou inaccessible.';end if;
 update private.research_jobs set cancelled_at=now() where id=j.id;update public.empires set treasury=treasury+j.cost where id=e;r:=jsonb_build_object('ok',true,'refunded',j.cost);
 else
 k:=p_args->>'technology';select spec into c from private.technology_catalog where key=k;if c is null then raise exception 'Technologie inconnue.';end if;
 select * into p from public.planets where id=(p_args->>'planet_id')::uuid and owner_empire_id=e for update;if not found and p_args->>'planet_id' is null and k in('energy','teleport') then select * into p from public.planets where owner_empire_id=e and not exists(select 1 from private.research_jobs j where j.planet_id=public.planets.id and j.completed_at is null and j.cancelled_at is null) order by serial limit 1 for update;end if;if p.id is null then raise exception 'Choisissez une de vos planètes.';end if;
 if exists(select 1 from private.research_jobs where planet_id=p.id and completed_at is null and cancelled_at is null) then raise exception 'Une recherche est déjà en cours sur cette planète.';end if;
 n:=private.tech_level(e,k)+1;if p_args ? 'expected_level' and (p_args->>'expected_level')::int<>n then raise exception 'Le niveau de recherche a changé. Actualisez.';end if;cost:=private.tech_price(k,n);if cost is null then raise exception 'Tous les niveaux sont déjà recherchés.';end if;
 if exists(select 1 from private.research_jobs where empire_id=e and key=k and completed_at is null and cancelled_at is null) then raise exception 'Cette technologie est déjà en recherche.';end if;
 if (c->>'race' is not null and c->>'race'<>p.race) or (c->>'resource' is not null and c->>'resource'<>p.resource) then raise exception 'Race ou ressource du laboratoire incompatible.';end if;
 if exists(select 1 from jsonb_array_elements(c->'requires')q where private.tech_level(e,q->>'key')<(q->>'level')::int) then raise exception 'Prérequis non recherchés.';end if;
 if private.ground_superiority(p.id,now()) then raise exception 'Recherche impossible sous supériorité ennemie au sol.';end if;
 if exists(select 1 from public.empires where id=e and (treasury<cost or maintenance_debt>0)) then raise exception 'Trésorerie insuffisante ou entretien à régulariser.';end if;
 update public.empires set treasury=treasury-cost where id=e;
 insert into private.research_jobs(empire_id,planet_id,key,level,cost,started_at,finishes_at) values(e,p.id,k,n,cost,now(),now()+make_interval(secs=>(private.tech_hours(k,n)*3600)::double precision)) returning * into j;
 r:=jsonb_build_object('ok',true,'id',j.id,'cost',cost,'finishes_at',j.finishes_at);
 end if;
 insert into private.technology_commands(empire_id,request_id,payload,result) values(e,p_request_id,payload,r);return r;
end $$;
-- Hook research completions into the existing event clock, including offline processing.
do $patch$ declare src text;begin
 select pg_get_functiondef('private.military_process(timestamptz)'::regprocedure) into src;
 if position('select least(coalesce(' in src)=0 then raise exception 'Unexpected military clock definition';end if;
 src:=replace(src,'select least(coalesce(','select least(coalesce((select min(r.finishes_at) from private.research_jobs r join public.planets rp on rp.id=r.planet_id where rp.season_id=s.id and r.completed_at is null and r.cancelled_at is null),''infinity''),coalesce(');
 src:=replace(src,'perform private.advance_planet_development(s.id,v_at);','perform private.advance_planet_development(s.id,v_at); perform private.research_complete(s.id,v_at);');
 execute src;
end $patch$;
create or replace function private.teleport_capture_network() returns trigger language plpgsql set search_path='' as $$
#variable_conflict use_column
begin if new.owner_empire_id is distinct from old.owner_empire_id then new.teleport_ready_at:=coalesce(nullif(current_setting('lw.development_at',true),'')::timestamptz,now())+make_interval(hours=>2*(select count(*)::int from public.planets where owner_empire_id=new.owner_empire_id));end if;return new;end $$;
-- Only future dispatches use travel research. Redirects start at the current position.
create function private.player_travel_seconds(e uuid,d double precision) returns int language sql stable set search_path='' as $$select ceil(private.travel_seconds(d)*power(.85,private.tech_level(e,'travel')))::int$$;
do $patch$ declare src text;begin
 select pg_get_functiondef('private.military_command(text,jsonb,uuid)'::regprocedure) into src;
 if position('private.travel_seconds(distance)' in src)=0 then raise exception 'Unexpected dispatch definition';end if;
 execute replace(src,'private.travel_seconds(distance)','private.player_travel_seconds(e,distance)');
 select pg_get_functiondef('private.technology_command_base(text,jsonb,uuid)'::regprocedure) into src;
 src:=replace(src,'(v_q::bigint+9)/10','ceil(v_q/(2.0*private.teleport_capacity(v_e)))');src:=replace(src,'(v_q::bigint+4)/5','ceil(v_q/private.teleport_capacity(v_e)::numeric)');
 src:=replace(src,'v_q>100-v_p.energy_max','v_q>private.energy_limit(v_e)-v_p.energy_max');
 execute src;
end $patch$;
revoke all on function private.tech_level(uuid,text),private.tech_price(text,int),private.tech_hours(text,int),private.teleport_capacity(uuid),private.energy_limit(uuid),private.research_complete(uuid,timestamptz),private.research_capture(),private.player_travel_seconds(uuid,double precision) from public,anon,authenticated;
revoke all on function private.technology_command(text,jsonb,uuid) from public,anon;grant execute on function private.technology_command(text,jsonb,uuid) to authenticated;
alter function private.technology_dashboard() rename to technology_dashboard_base;
revoke all on function private.technology_dashboard_base() from public,anon,authenticated;
create function private.technology_dashboard() returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column

declare e uuid;r jsonb;catalog jsonb;jobs jsonb;
begin
 e:=private.active_player_id();r:=private.technology_dashboard_base();
 select jsonb_agg(c.spec||jsonb_build_object('level',private.tech_level(e,c.key),'next_cost',private.tech_price(c.key,private.tech_level(e,c.key)+1),'next_hours',private.tech_hours(c.key,private.tech_level(e,c.key)+1),
 'prerequisites_met',not exists(select 1 from jsonb_array_elements(c.spec->'requires')q where private.tech_level(e,q->>'key')<(q->>'level')::int),
 'eligible_planets',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'race',p.race,'resource',p.resource,'busy',exists(select 1 from private.research_jobs j where j.planet_id=p.id and j.completed_at is null and j.cancelled_at is null))) from public.planets p where p.owner_empire_id=e and (c.spec->>'race' is null or c.spec->>'race'=p.race) and(c.spec->>'resource' is null or c.spec->>'resource'=p.resource)),'[]'::jsonb))) into catalog from private.technology_catalog c;
 select coalesce(jsonb_agg(to_jsonb(j)||jsonb_build_object('planet',private.military_label(j.planet_id,e),'name',c.spec->>'name') order by j.finishes_at),'[]'::jsonb) into jobs from private.research_jobs j join private.technology_catalog c on c.key=j.key where j.empire_id=e and j.completed_at is null and j.cancelled_at is null;
 return r||jsonb_build_object('catalog',catalog,'research_jobs',jobs,'teleport_capacity',private.teleport_capacity(e),'storage_limit',private.energy_limit(e));
end $$;
revoke all on function private.technology_dashboard() from public,anon;grant execute on function private.technology_dashboard() to authenticated;
-- These discounts change purchases, never the yield or the previously paid price.
create function private.capacity_price_for(pid uuid,n int) returns bigint language sql stable set search_path='' as $$
 select ceil(private.capacity_price(n)*case when p.civilization<=greatest(
 case when private.tech_level(p.owner_empire_id,'workers_1')>0 then 4 else 0 end,
 case when private.tech_level(p.owner_empire_id,'workers_2')>0 then 5 else 0 end,
 case when private.tech_level(p.owner_empire_id,'cybernetics_1')>0 then 7 else 0 end,
 case when private.tech_level(p.owner_empire_id,'cybernetics_2')>0 then 9 else 0 end,
 case when private.tech_level(p.owner_empire_id,'exploitation_'||p.resource)>0 then private.tech_level(p.owner_empire_id,'exploitation_'||p.resource)+5 else 0 end) then .7 else 1 end)::bigint
 from public.planets p where p.id=pid;
$$;
do $patch$ declare f record;src text;begin
 for f in select oid from pg_proc where pronamespace='private'::regnamespace and prosrc like '%sum(private.capacity_price(n))%' loop
 select pg_get_functiondef(f.oid) into src;
 if position('v_source' in src)=0 then raise exception 'Unknown capacity purchase context';end if;
 execute replace(src,'private.capacity_price(n)','private.capacity_price_for(v_source.id,n)');end loop;
end $patch$;
alter function private.trade_dashboard(uuid) rename to trade_dashboard_before_research;
revoke all on function private.trade_dashboard_before_research(uuid) from public,anon,authenticated;
create function private.trade_dashboard(p_planet_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare r jsonb;begin
 r:=private.trade_dashboard_before_research(p_planet_id);
 return r||jsonb_build_object('prices',coalesce((select jsonb_agg(private.capacity_price_for(p_planet_id,n) order by n) from public.planets p cross join lateral generate_series(p.trade_capacity+1,200)n where p.id=p_planet_id),'[]'::jsonb));end $$;
revoke all on function private.trade_dashboard(uuid) from public,anon;grant execute on function private.trade_dashboard(uuid) to authenticated;
alter function private.planet_overview() rename to planet_overview_before_research;
revoke all on function private.planet_overview_before_research() from public,anon,authenticated;
create function private.planet_overview() returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare r jsonb;begin
 r:=private.planet_overview_before_research();
 return jsonb_set(r,'{planets}',coalesce((select jsonb_agg(x||jsonb_build_object('prices',(select jsonb_object_agg(n::text,private.capacity_price_for((x->>'id')::uuid,n)) from generate_series(1,200)n))) from jsonb_array_elements(r->'planets')x),'[]'::jsonb));end $$;
revoke all on function private.planet_overview() from public,anon;grant execute on function private.planet_overview() to authenticated;
